// MT2009_PLUS_SHOP_SEARCH_PLUS_V1 (server-patches/playerqol): the search's
// "MT2009 Plus" category, one past the package's last (the operator, 28
// September): 0 the Cor Draconis, 1-4 the sashes by grade whatever their
// look, 5-7 the ancient, legendary and mythic alchemy whatever the stone
// and its steps. Built on the first search, from the item table the boot
// has loaded by then - PrepareShopSearchFilters runs before it.
template <class FILTERS>
static void Mt2009PlusShopSearchFilters(FILTERS& filters)
{
	typedef typename FILTERS::mapped_type::value_type FILTER;
	const DWORD base = SHOP_SEARCH_CATEGORY_MAX * SHOP_CATEGORY_MAX_SUB;
	// The four the operator keeps in the tab (28 September).
	static const DWORD cors[] = { 50255, 50256, 50257, 50258, 50259 };
	for (size_t i = 0; i < sizeof(cors) / sizeof(cors[0]); ++i)
		if (ITEM_MANAGER::instance().GetTable(cors[i]))
		{
			FILTER f;
			f.itemVnum = cors[i];
			f.socket0 = 0;
			filters[base + 0].push_back(f);
		}
	static const DWORD sashRanges[][2] = { { 85001, 85024 }, { 85101, 85104 }, { 86061, 86064 } };
	for (size_t r = 0; r < sizeof(sashRanges) / sizeof(sashRanges[0]); ++r)
		for (DWORD vnum = sashRanges[r][0]; vnum <= sashRanges[r][1]; ++vnum)
		{
			const TItemTable* proto = ITEM_MANAGER::instance().GetTable(vnum);
			if (!proto || proto->bType != ITEM_COSTUME || proto->alValues[0] < 1 || proto->alValues[0] > 4)
				continue;
			FILTER f;
			f.itemVnum = vnum;
			f.socket0 = 0;
			filters[base + (DWORD) proto->alValues[0]].push_back(f);
		}
	for (DWORD kind = 11; kind <= 16; ++kind)
		for (DWORD grade = 3; grade <= 5; ++grade)
			for (DWORD rest = 0; rest < 1000; ++rest)
			{
				const DWORD vnum = kind * 10000 + grade * 1000 + rest;
				const TItemTable* proto = ITEM_MANAGER::instance().GetTable(vnum);
				if (!proto || proto->bType != ITEM_DS)
					continue;
				FILTER f;
				f.itemVnum = vnum;
				f.socket0 = 0;
				filters[base + 5 + (grade - 3)].push_back(f);
			}
}

