		iDur += iDur / 2;
	if (iDur2 > 0 && bBuff)
		iDur2 += iDur2 / 2;
	if (iDur3 > 0 && (bBuff || IS_SET(pkSk->dwFlag, SKILL_FLAG_THIRD_POINT_SELFONLY)))
		iDur3 += iDur3 / 2;
	if (test_server)
		sys_log(0, "SKILL_DURATION_GM: %s skill %u grade %d dur %d %d %d", ch->GetName(), pkSk->dwVnum, ch->GetSkillMasterType(pkSk->dwVnum), iDur, iDur2, iDur3);
